16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * The Luhn check-digit algorithm.
20	 *
21	 * <p>Computes the single check digit (0-9) over the decimal digits contained in a
22	 * string, ignoring any non-digit characters. This is the single source of truth for
23	 * that computation, so callers never repeat it.
24	 */
25	public final class LuhnCheckDigit {
26	
27	    private LuhnCheckDigit() {
28	    }
29	
30	    /**
31	     * Compute the Luhn check digit over the digits contained in {@code value}.
32	     *
33	     * @param value the string whose digits are checked; non-digit characters are ignored
34	     * @return the check digit (0-9) that, appended to the digits, makes them Luhn-valid
35	     */
36	    public static int of(String value) {
37	        int sum = 0;
38	        boolean doubling = true;
39	        for (int i = value.length() - 1; i >= 0; i--) {
40	            char c = value.charAt(i);
41	            if (c < '0' || c > '9') {
42	                continue;
43	            }
44	            int d = c - '0';
45	            if (doubling) {
46	                d *= 2;
47	                if (d > 9) {
48	                    d -= 9;
49	                }
50	            }
51	            sum += d;
52	            doubling = !doubling;
53	        }
54	        return (10 - (sum % 10)) % 10;
55	    }
56	}
