16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "bulk_signup_warning")
67	    private Boolean bulkSignupWarning;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @Column(name = "postcode")
73	    private String postcode;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public LocalDate getRegistrationDate() {
111	        return this.registrationDate;
112	    }
113	
114	    public void setRegistrationDate(LocalDate registrationDate) {
115	        this.registrationDate = registrationDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    public void setCustomerCode(String customerCode) {
123	        this.customerCode = customerCode;
124	    }
125	
126	    public String getHouseholdId() {
127	        return this.householdId;
128	    }
129	
130	    public void setHouseholdId(String householdId) {
131	        this.householdId = householdId;
132	    }
133	
134	    public Integer getNamesakeCount() {
135	        return this.namesakeCount;
136	    }
137	
138	    public void setNamesakeCount(Integer namesakeCount) {
139	        this.namesakeCount = namesakeCount;
140	    }
141	
142	    public Boolean getBulkSignupWarning() {
143	        return this.bulkSignupWarning;
144	    }
145	
146	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
147	        this.bulkSignupWarning = bulkSignupWarning;
148	    }
149	
150	    public Integer getHouseholdSize() {
151	        return this.householdSize;
152	    }
153	
154	    public void setHouseholdSize(Integer householdSize) {
155	        this.householdSize = householdSize;
156	    }
157	
158	    public String getPostcode() {
159	        return this.postcode;
160	    }
161	
162	    public void setPostcode(String postcode) {
163	        this.postcode = postcode;
164	    }
165	
166	    /**
167	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
168	     * is the last two digits of the registration date's year (e.g. {@code "SMI-0007-M26"}).
169	     * Derived from the owner's own fields, so it stays consistent with them.
170	     */
171	    @Transient
172	    public String getMembershipNumber() {
173	        if (this.customerCode == null || this.registrationDate == null) {
174	            return null;
175	        }
176	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
177	    }
178	
179	    /**
180	     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
181	     * over the digits of the customer code. Derived from the owner's own customer code,
182	     * so it stays consistent with it.
183	     */
184	    @Transient
185	    public Integer getCheckDigit() {
186	        if (this.customerCode == null) {
187	            return null;
188	        }
189	        return LuhnCheckDigit.of(this.customerCode);
190	    }
191	
192	    /**
193	     * The owner's membership level, a number from 1 to 3. Every owner starts at level 1;
194	     * one level is added when an email is on file and one more when the owner is unique
195	     * (namesake count of zero). The level is capped at 3, leaving level 4 reserved for
196	     * tenure. Derived from the owner's own fields, so it stays consistent with them.
197	     */
198	    @Transient
199	    public Integer getMembershipLevel() {
200	        int level = 1;
201	        boolean hasEmail = this.email != null && !this.email.isEmpty();
202	        if (hasEmail) {
203	            level++;
204	        }
205	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
206	        if (unique) {
207	            level++;
208	        }
209	        return Math.min(level, 3);
210	    }
211	
212	    /**
213	     * The owner's locality: the canonical region. This prefers the postcode, resolving the
214	     * region whose range contains it (see {@link RegionPostcodeTable}), and only falls back
215	     * to the city via the fixed {@link CityRegionTable} when the postcode is absent or in no
216	     * known range. Derived from the owner's own fields, so it stays consistent with them.
217	     */
218	    @Transient
219	    public String getLocality() {
220	        return RegionPostcodeTable.regionFor(this.postcode)
221	            .orElseGet(() -> CityRegionTable.regionFor(this.city));
222	    }
223	
224	    /**
225	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
226	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
227	     * stays consistent with them.
228	     */
229	    @Transient
230	    public String getContactPreference() {
231	        boolean hasEmail = this.email != null && !this.email.isEmpty();
232	        return hasEmail ? "EMAIL" : "PHONE";
233	    }
234	
235	    /**
236	     * The owner's identity key: the single derived value used to detect duplicate owners,
237	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
238	     * Two owners are duplicates only when their whole identity keys are equal, so members
239	     * of one household (sharing a household id) but with different telephones stay distinct.
240	     * Derived from the owner's own fields, so it stays consistent with them.
241	     */
242	    @Transient
243	    public String getIdentityKey() {
244	        String telephonePart = this.telephone == null ? "" : this.telephone;
245	        String emailPart = this.email == null ? "" : this.email;
246	        String householdPart = this.householdId == null ? "" : this.householdId;
247	        return telephonePart + "|" + emailPart + "|" + householdPart;
248	    }
249	
250	    /**
251	     * Normalize the registration date before persisting: default it to the server's
252	     * current date when none was supplied, then roll it forward onto a business day so
253	     * every newly persisted owner is registered on a weekday.
254	     */
255	    @PrePersist
256	    void normalizeRegistrationDate() {
257	        if (this.registrationDate == null) {
258	            this.registrationDate = LocalDate.now();
259	        }
260	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
261	    }
262	
263	    protected Set<Pet> getPetsInternal() {
264	        if (this.pets == null) {
265	            this.pets = new HashSet<>();
266	        }
267	        return this.pets;
268	    }
269	
270	    protected void setPetsInternal(Set<Pet> pets) {
271	        this.pets = pets;
272	    }
273	
274	    public List<Pet> getPets() {
275	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
276	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
277	        return Collections.unmodifiableList(sortedPets);
278	    }
279	
280	    public void setPets(List<Pet> pets) {
281	        this.pets = new HashSet<>(pets);
282	    }
283	
284	    public void addPet(Pet pet) {
285	        getPetsInternal().add(pet);
286	        pet.setOwner(this);
287	    }
288	
289	    /**
290	     * Return the Pet with the given name, or null if none found for this Owner.
291	     *
292	     * @param name to test
293	     * @return true if pet name is already in use
294	     */
295	    public Pet getPet(String name) {
296	        return getPet(name, false);
297	    }
298	
299	    /**
300	     * Return the Pet with the given name, or null if none found for this Owner.
301	     *
302	     * @param name to test
303	     * @return true if pet name is already in use
304	     */
305	    public Pet getPet(String name, boolean ignoreNew) {
306	        name = name.toLowerCase();
307	        for (Pet pet : getPetsInternal()) {
308	            if (!ignoreNew || !pet.isNew()) {
309	                String compName = pet.getName();
310	                compName = compName.toLowerCase();
311	                if (compName.equals(name)) {
312	                    return pet;
313	                }
314	            }
315	        }
316	        return null;
317	    }
318	
319	    public Pet getPet(Integer petId) {
320	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
321	    }
322	
323	    @Override
324	    public String toString() {
325	        return new ToStringCreator(this)
326	
327	            .append("id", this.getId())
328	            .append("new", this.isNew())
329	            .append("lastName", this.getLastName())
330	            .append("firstName", this.getFirstName())
331	            .append("address", this.address)
332	            .append("city", this.city)
333	            .append("telephone", this.telephone)
334	            .toString();
335	    }
336	}
