23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Derives a household's stable, shared identifier from its last name and address.
27	 *
28	 * <p>Owners belong to the same household when they share a last name and address,
29	 * compared case-insensitively and ignoring differences in surrounding or repeated
30	 * whitespace. Because the identifier is a deterministic hash of that normalized
31	 * identity, every owner in a household maps to the same value, independently and
32	 * across requests.
33	 */
34	@Component
35	public class HouseholdIdGenerator {
36	
37	    private static final String PREFIX = "HH-";
38	
39	    private static final int ID_LENGTH = 12;
40	
41	    /**
42	     * Build the shared household identifier for the household identified by the given
43	     * last name and address.
44	     *
45	     * @param lastName the household's last name
46	     * @param address  the household's address
47	     * @return the stable household identifier, e.g. {@code "HH-0A1B2C3D4E5F"}
48	     */
49	    public String generate(String lastName, String address) {
50	        String identity = normalize(lastName) + "\n" + normalize(address);
51	        return PREFIX + sha256Hex(identity).substring(0, ID_LENGTH).toUpperCase(Locale.ROOT);
52	    }
53	
54	    /**
55	     * Normalize a household identity value for comparison: trim, collapse each run of
56	     * whitespace to a single space and lower-case, so that differences in case or
57	     * spacing do not split what is really one household.
58	     */
59	    private static String normalize(String value) {
60	        if (value == null) {
61	            return "";
62	        }
63	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
64	    }
65	
66	    private static String sha256Hex(String value) {
67	        try {
68	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
69	            StringBuilder hex = new StringBuilder(digest.length * 2);
70	            for (byte b : digest) {
71	                hex.append(String.format("%02x", b));
72	            }
73	            return hex.toString();
74	        }
75	        catch (NoSuchAlgorithmException e) {
76	            throw new IllegalStateException("SHA-256 is required but not available", e);
77	        }
78	    }
79	}
