 * first three letters of the last name and NNNN is a per-city 4-digit zero-padded
 * sequence.
 */
@Component
public class CustomerCodeGenerator {

    private static final int PREFIX_LENGTH = 3;

    /**
     * Build the customer code for a new owner.
     *
